const $=s=>document.querySelector(s),pct=x=>x==null?'—':(x*100).toFixed(2)+'%',num=(x,n=2)=>x==null?'—':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:n,minimumFractionDigits:n});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colored=x=>`<span class="${x>=0?'pos':'neg'}">${pct(x)}</span>`;
const table=(headers,rows)=>`<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr${r.selected?' class="chosen"':''}>${r.values.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const reasonNames={FILLED:'已成交',LOT_CAPACITY_CASH_OR_LOCK:'部分成交：数量／容量／资金限制',CASH_LOT_CAPACITY_OR_DELIVERY_LOCK:'资金／最小股数／容量／锁定限制',CORPORATE_ACTION_CANCEL_REPLAN_AT_CLOSE:'除权日取消旧数量计划',SLIPPAGE_OUTSIDE_OBSERVED_RANGE:'滑点价超出日线价格范围',LIMIT_UP_CANNOT_BUY:'涨停，拒绝买入',LIMIT_DOWN_CANNOT_SELL:'跌停，拒绝卖出',SUSPENDED:'停牌',ST_EXCLUDED_AT_EXECUTION:'执行日为ST，拒买',UNKNOWN_HISTORICAL_STATE:'历史状态未知',SLIPPAGE_OUTSIDE_BOUNDS:'滑点价越过涨跌停',SLIPPAGE_AT_LIMIT_UP:'滑点价达到涨停，拒买',SLIPPAGE_AT_LIMIT_DOWN:'滑点价达到跌停，拒卖'};let data,key;
function metrics(k){key=k;let m=data.summary.comparison.find(x=>x.key===k);$('#selected-title').textContent=m.strategy;$('.study-head .eyebrow').textContent=k===data.summary.selected_key?'FROZEN MODEL':'BASELINE MODEL';$('.study-head p').textContent=k===data.summary.selected_key?'由2024年训练结果选出；评价期不重新选冠军。':'当前查看基础版指标；冻结方案仍由2024年训练结果确定。';$('#total').innerHTML=colored(m.total_return);$('#drawdown').innerHTML=colored(m.max_drawdown);$('#exposure').textContent=pct(m.average_exposure);$('#turnover').textContent=num(m.turnover_one_way)+'×';$('#show-selected').classList.toggle('active',k===data.summary.selected_key);$('#show-base').classList.toggle('active',k==='base')}
function plot(){let s=data.summary.selected_key,base=data.equity.base,chosen=data.equity[s],benchmark=data.summary.benchmark||[];let series=[{data:base.map(r=>r.net_value),color:'#a8b49b'},{data:chosen.map(r=>r.net_value),color:'#b56b45'}];if(benchmark.length===base.length)series.push({data:benchmark.map(r=>r.net_value),color:'#526e78'});let all=series.flatMap(s=>s.data).filter(Number.isFinite),lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*.1||.05;lo-=pad;hi+=pad;let W=900,H=280,L=45,R=15,T=15,B=35,w=W-L-R,h=H-T-B;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="基础5DR、冻结方案与沪深300的净值比较">`;for(let j=0;j<5;j++){let y=T+j*h/4,v=hi-(hi-lo)*j/4;svg+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="#e2e6d8"/><text x="${L-8}" y="${y+3}" text-anchor="end">${v.toFixed(2)}</text>`}for(let i of [0,Math.floor(base.length/3),Math.floor(base.length*2/3),base.length-1])svg+=`<text x="${L+i*w/(base.length-1)}" y="${H-7}" text-anchor="${i===0?'start':i===base.length-1?'end':'middle'}">${base[i].date}</text>`;series.forEach(v=>svg+=`<polyline fill="none" stroke="${v.color}" stroke-width="2.2" stroke-linejoin="round" points="${v.data.map((y,i)=>`${L+i*w/(base.length-1)},${T+(hi-y)*h/(hi-lo)}`).join(' ')}"/>`);$('#chart').innerHTML=svg+'</svg>'}
async function load(){try{let r=await fetch('/api/5dr-review');if(!r.ok)throw Error('研究结果尚未生成，请先按运行说明完成回测。');data=await r.json();let s=data.summary,chosen=s.comparison.find(x=>x.key===s.selected_key);$('#selected-title').textContent=chosen.strategy;$('#selected-legend').textContent=chosen.strategy;metrics(s.selected_key);plot();$('#comparison').innerHTML=table(['方案','累计收益','最大回撤','平均仓位','单边换手','费用（元）'],s.comparison.map(x=>({selected:x.selected_on_2024,values:[esc(x.strategy),colored(x.total_return),pct(x.max_drawdown),pct(x.average_exposure),num(x.turnover_one_way)+'×',num(x.total_fees,0)]})));$('#periods').innerHTML=table(['区间','基础5DR','冻结方案'],['2025','2026年前三季度'].map(p=>({values:[p,colored(s.periods.find(x=>x.key==='base'&&x.period===p)?.total_return),colored(s.periods.find(x=>x.key===s.selected_key&&x.period===p)?.total_return)]})));let names={double_cost:'双倍费用与滑点',tight_capacity:'日均成交额 0.1% 上限',gross_dividend:'现金股利不扣税',carry_stale:'缺价继续保留旧估值'};$('#stress').innerHTML=table(['场景','累计收益','最大回撤'],s.stress.filter(x=>x.key===s.selected_key).map(x=>({values:[names[x.scenario]||esc(x.scenario),colored(x.total_return),pct(x.max_drawdown)]})));$('#focus').innerHTML=table(['股票','方案','累计收益','最大回撤'],(s.focus_stocks||[]).map(x=>({values:[esc(x.symbol),esc(x.strategy),colored(x.total_return),pct(x.max_drawdown)]})));$('#risk-note').textContent=`冻结方案风险复核：2026年前三季度 ${pct(s.periods.find(x=>x.key===s.selected_key&&x.period==='2026年前三季度').total_return)} · 双倍税费与滑点下累计 ${pct(s.stress.find(x=>x.key===s.selected_key&&x.scenario==='double_cost').total_return)}。改进后仍有高回撤与成本敏感性。`;let v=data.validation;$('#audit-text').textContent=v?`${v.passed?'账本校验通过':'存在待复核项目'} · ${v.runs_checked} 组运行独立重放。历史状态与课程收盘价比较 ${num(s.data_audit.raw_close_compared,0)} 格；超过半分钱的差异 ${s.data_audit.raw_close_mismatched} 格；有成交报价的历史状态覆盖 ${pct(s.precision_audit.known_state_coverage)}。`:'账本校验尚未生成。';$('#orders-count').textContent=`冻结方案：${chosen.filled_orders} 笔成交 / ${chosen.rejected_orders} 笔拒单`;$('#orders').innerHTML=table(['执行日','代码','方向','计划股数','成交股数','成交价','状态 / 原因'],data.orders.slice(-16).reverse().map(x=>({values:[x.execution_date,esc(x.symbol),x.side==='BUY'?'买入':'卖出',num(x.planned_qty,0),num(x.filled_qty,0),num(x.raw_execution_price),esc(reasonNames[x.reason]||x.reason)]})));$('#limitations').textContent='精度边界：历史 ST 使用生效日标记，假设盘前可知；涨跌停由历史前收与板块规则重建，未取得交易所逐日官方限价文件。开盘价加滑点仍是成交代理。现金股利统一扣税20%；零股分配、完整个税及特殊公司行为仍有简化。连续缺价20日减记为零，保留股份，不表示实际清仓。期末不强制卖出。';$('#show-selected').onclick=()=>metrics(s.selected_key);$('#show-base').onclick=()=>metrics('base');$('#loading').hidden=true;$('#content').hidden=false}catch(e){$('#loading').textContent=e.message}}
load();
